// Estimates HubSpot actions used this month from the Leads tab.
// Counting rule (HubSpot free plan, 3,000 actions/month): first email = 2 (contact upsert + logged email),
// each follow-up = 1 (logged email), each reply = 2 (logged email + lead status).
// Follow-up dates are estimated as Sent At + 7 / +14 / +21 days.
const rows = $('Get All Leads').all().map(i => i.json).filter(r => r && r['Lead ID']);
const settings = ($('Read Settings').first() || {}).json || {};
const limit = Number(settings['HubSpot Monthly Limit']) || 3000;
const pauseAt = Number(settings['HubSpot Pause Percent']) || 80;

const now = new Date();
const y = now.getUTCFullYear();
const m = now.getUTCMonth();
const inMonth = (d) => { const t = new Date(d); return !isNaN(t) && t.getUTCFullYear() === y && t.getUTCMonth() === m; };
const addDays = (d, n) => { const t = new Date(d); t.setUTCDate(t.getUTCDate() + n); return t; };
const offsets = [7, 14, 21];

let used = 0;
const detail = { firstEmails: 0, followUps: 0, replies: 0 };
for (const r of rows) {
  const sentAt = r['Sent At'];
  const sentValid = sentAt && !isNaN(new Date(sentAt));
  if (sentValid && inMonth(sentAt)) { used += 2; detail.firstEmails++; }
  const fu = Math.min(Number(r['Follow-up Count'] || 0), 3);
  if (sentValid) {
    for (let k = 0; k < fu; k++) {
      if (inMonth(addDays(sentAt, offsets[k]))) { used += 1; detail.followUps++; }
    }
  }
  if (String(r['Reply Category'] || '') !== '' && inMonth(r['Last Updated'])) { used += 2; detail.replies++; }
}

const percent = Math.round((used / limit) * 100);
return [{ json: {
  hubspot_actions_used: used,
  hubspot_limit: limit,
  percent,
  pause_at: pauseAt,
  paused: percent >= pauseAt,
  detail,
  nil_email: settings['Nil Email'] || '',
  sheet_url: settings['Sheet URL'] || '',
} }];

// Daily inbox-placement copy: once a day (18:00), send an identical copy of the LAST first email sent today to Settings 'Seed Email'.
// Blank Seed Email = off. Nothing sent today = no copy.
const s = $('Seed: Read Settings').first().json || {};
const seed = String(s['Seed Email'] || '').trim();
if (!seed) return [];
const today = $now.setZone('Europe/Istanbul').toISODate();
let last = null, lastT = null;
for (const i of $('Seed: Read Leads').all()) {
  const r = i.json || {};
  const raw = String(r['Sent At'] || '').trim();
  if (!raw || !r['Lead ID'] || !String(r['Draft Body'] || '').trim()) continue;
  const t = DateTime.fromISO(raw);
  if (!t.isValid || t.setZone('Europe/Istanbul').toISODate() !== today) continue;
  if (!lastT || t > lastT) { last = r; lastT = t; }
}
if (!last) return [];
return [{ json: { seed, from: s['SMTP From'], subject: last.Subject, body: last['Draft Body'], html: buildHtml(last['Draft Body'], s), lead: last['Lead ID'], sent_at: last['Sent At'] } }];
// Turns the plain-text draft into a light HTML version (sent alongside the plain text).
// Looks like a personal email: no images, no banners; a tidy signature and a small grey footer.
function buildHtml(body, s) {
  const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const link = (t) => t.replace(/(https?:\/\/[^\s<]+)/g, (u) => '<a href="' + u + '" style="color:#0e7490;text-decoration:none;">' + u.replace(/^https?:\/\//, '').replace(/\/$/, '') + '</a>');
  const lines = String(body || '').replace(/\r/g, '').split('\n');
  const name = String(s['Sender Name'] || '').trim();
  const title = String(s['Sender Title'] || '').trim();
  const company = String(s['Company Legal Name'] || '').trim();
  const iName = name ? lines.findIndex(l => l.trim() === name) : -1;
  const paras = (arr) => arr.join('\n').split(/\n\s*\n/).map(p => p.trim()).filter(Boolean);
  const P = (p, style) => '<p style="margin:0 0 16px;' + (style || '') + '">' + link(esc(p)).replace(/\n/g, '<br>') + '</p>';
  if (iName < 0) {
    return '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#1f2937;max-width:600px;">' + paras(lines).map(p => P(p)).join('') + '</div>';
  }
  let iEnd = iName;
  while (iEnd + 1 < lines.length && lines[iEnd + 1].trim()) iEnd++;
  const main = paras(lines.slice(0, iName));
  const sig = lines.slice(iName, iEnd + 1).map(l => l.trim());
  const foot = paras(lines.slice(iEnd + 1));
  const sigHtml = sig.map((l, i) => {
    const t = link(esc(l));
    if (i === 0) return '<div style="font-size:15px;font-weight:bold;color:#111827;">' + t + '</div>';
    if (l === title) return '<div style="color:#4b5563;">' + t + '</div>';
    if (l === company) return '<div style="font-weight:bold;color:#0e7490;margin-top:2px;">' + t + '</div>';
    if (/^https?:\/\//.test(l)) return '<div style="margin-top:2px;">' + t + '</div>';
    return '<div style="font-size:13px;color:#6b7280;">' + t + '</div>';
  }).join('');
  return '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#1f2937;max-width:600px;">'
    + main.map(p => P(p)).join('')
    + '<table role="presentation" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:4px 0 0;"><tr><td style="border-left:3px solid #0e7490;padding:2px 0 2px 12px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#1f2937;">' + sigHtml + '</td></tr></table>'
    + (foot.length ? '<div style="margin-top:28px;padding-top:12px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.5;color:#9ca3af;">' + foot.map(p => P(p, 'margin:0 0 6px;')).join('') + '</div>' : '')
    + '</div>';
}

// HTML copy of the approved draft; the plain text is sent alongside it.
return { json: { ...$json, html: buildHtml($json['Draft Body'], $('Read Settings').first().json) } };

// Turns the plain-text draft into a light HTML version (sent alongside the plain text).
// Looks like a personal email: no images, no banners; a tidy signature and a small grey footer.
function buildHtml(body, s) {
  const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const link = (t) => t.replace(/(https?:\/\/[^\s<]+)/g, (u) => '<a href="' + u + '" style="color:#0e7490;text-decoration:none;">' + u.replace(/^https?:\/\//, '').replace(/\/$/, '') + '</a>');
  const lines = String(body || '').replace(/\r/g, '').split('\n');
  const name = String(s['Sender Name'] || '').trim();
  const title = String(s['Sender Title'] || '').trim();
  const company = String(s['Company Legal Name'] || '').trim();
  const iName = name ? lines.findIndex(l => l.trim() === name) : -1;
  const paras = (arr) => arr.join('\n').split(/\n\s*\n/).map(p => p.trim()).filter(Boolean);
  const P = (p, style) => '<p style="margin:0 0 16px;' + (style || '') + '">' + link(esc(p)).replace(/\n/g, '<br>') + '</p>';
  if (iName < 0) {
    return '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#1f2937;max-width:600px;">' + paras(lines).map(p => P(p)).join('') + '</div>';
  }
  let iEnd = iName;
  while (iEnd + 1 < lines.length && lines[iEnd + 1].trim()) iEnd++;
  const main = paras(lines.slice(0, iName));
  const sig = lines.slice(iName, iEnd + 1).map(l => l.trim());
  const foot = paras(lines.slice(iEnd + 1));
  const sigHtml = sig.map((l, i) => {
    const t = link(esc(l));
    if (i === 0) return '<div style="font-size:15px;font-weight:bold;color:#111827;">' + t + '</div>';
    if (l === title) return '<div style="color:#4b5563;">' + t + '</div>';
    if (l === company) return '<div style="font-weight:bold;color:#0e7490;margin-top:2px;">' + t + '</div>';
    if (/^https?:\/\//.test(l)) return '<div style="margin-top:2px;">' + t + '</div>';
    return '<div style="font-size:13px;color:#6b7280;">' + t + '</div>';
  }).join('');
  return '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#1f2937;max-width:600px;">'
    + main.map(p => P(p)).join('')
    + '<table role="presentation" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:4px 0 0;"><tr><td style="border-left:3px solid #0e7490;padding:2px 0 2px 12px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#1f2937;">' + sigHtml + '</td></tr></table>'
    + (foot.length ? '<div style="margin-top:28px;padding-top:12px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.5;color:#9ca3af;">' + foot.map(p => P(p, 'margin:0 0 6px;')).join('') + '</div>' : '')
    + '</div>';
}

// Warm-up cap: at most Settings 'Daily Send Limit' first emails per Istanbul calendar day (default 10).
// Counts leads whose Sent At is today (read at the start of this run) and only lets the remainder through.
// Also holds back what must not go yet (Nil's decisions of 23 Nov 2026):
// - a row that already has a Sent At (never send twice);
// - a second contact (row with 'Parent Lead ID'): only when the first person was mailed at least 3 days ago and
//   has not replied, or when the first person's mail bounced. If the first person replied, it is not sent.
const s = $('Read Settings').first().json || {};
const limit = parseInt(s['Daily Send Limit'], 10);
const cap = Number.isFinite(limit) && limit >= 0 ? limit : 10;
const now = $now.setZone('Europe/Istanbul');
const today = now.toISODate();
const all = $('Get All Leads').all().map(i => i.json || {});
const byId = {};
for (const r of all) if (r['Lead ID']) byId[String(r['Lead ID']).trim()] = r;
const sentToday = all.filter(r => {
  const raw = String(r['Sent At'] || '').trim();
  if (!raw) return false;
  const t = DateTime.fromISO(raw);
  return t.isValid && t.setZone('Europe/Istanbul').toISODate() === today;
}).length;
const ready = $input.all().filter(i => {
  const j = i.json || {};
  if (String(j['Sent At'] || '').trim()) return false;
  const pid = String(j['Parent Lead ID'] || '').trim();
  if (!pid) return true;
  const p = byId[pid];
  if (!p) return false;
  if (p.Stage === 'Bounced') return true;
  if (String(p['Reply Category'] || '').trim() || p['Opt-out'] === 'Yes') return false;
  if (!['Sent', 'Follow-up 1', 'Follow-up 2', 'Follow-up 3'].includes(p.Stage)) return false;
  const t = DateTime.fromISO(String(p['Sent At'] || '').trim());
  return t.isValid && t.setZone('Europe/Istanbul').plus({ days: 3 }).toISODate() <= today;
});
const remaining = Math.max(0, cap - sentToday);
return ready.slice(0, remaining);

// End-of-run Telegram summary (user 2026-11-16): which first emails this run sent, today's total vs the daily cap,
// skips, and how many approved emails are still waiting. Runs once on the loop's "done" output.
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const s = $('Read Settings').first().json || {};
const chatId = String(s['Nil Telegram Chat ID'] || '').trim();
if (!chatId) return [];
const leads = $('Get All Leads').all().map(i => i.json || {});
const byId = {};
for (const r of leads) if (r['Lead ID']) byId[r['Lead ID']] = r;
const items = $input.all().map(i => i.json || {});
const sent = items.filter(j => j.Stage === 'Sent' && j['Sent At']);
const skipped = items.filter(j => !(j.Stage === 'Sent' && j['Sent At']));
if (!sent.length && !skipped.length && !leads.some(r => r.Stage === 'Sending')) return [];
const today = $now.setZone('Europe/Istanbul').toISODate();
const sentBefore = leads.filter(r => {
  const t = DateTime.fromISO(String(r['Sent At'] || '').trim());
  return t.isValid && t.setZone('Europe/Istanbul').toISODate() === today;
}).length;
const limit = parseInt(s['Daily Send Limit'], 10);
const cap = Number.isFinite(limit) && limit >= 0 ? limit : 10;
const approved = $('Get Approved Drafts').all().length;
const waiting = Math.max(0, approved - items.length);
const dash = String(s['Dashboard URL'] || '').trim().replace(/\/+$/, '');
const lines = ['<b>Texprove: ' + sent.length + ' first email' + (sent.length === 1 ? '' : 's') + ' sent</b> (' + (sentBefore + sent.length) + ' of ' + cap + ' today)'];
for (const j of sent) {
  const r = byId[j['Lead ID']] || {};
  const t = DateTime.fromISO(String(j['Sent At'])).setZone('Europe/Istanbul').toFormat('HH:mm');
  lines.push('• ' + esc(t) + ' ' + esc(r.Company || j['Lead ID']) + (r.Email ? ' (' + esc(r.Email) + ')' : ''));
}
if (skipped.length) lines.push('Skipped ' + skipped.length + ' (opted out, blocked, on the Suppression list, or changed since approval): ' + esc(skipped.map(j => j['Lead ID']).join(', ')));
const stuck = leads.filter(r => r.Stage === 'Sending').map(r => r['Lead ID']);
if (stuck.length) lines.push('Needs a look: ' + esc(stuck.join(', ')) + ' still at stage Sending from an earlier run that stopped mid-send. Check the Sent folder, then set the stage to Sent or back to Drafted.');
lines.push(waiting ? waiting + ' approved email' + (waiting === 1 ? '' : 's') + ' waiting for the next run.' : 'No approved emails waiting.');
if (dash) lines.push(esc(dash));
return [{ json: { chatId, text: lines.join('\n').slice(0, 4000) } }];

// Only one sending run at a time (three emails went out twice on 18 Nov when two runs overlapped).
// Settings 'WF3 Lock' holds the start time of the run that is sending. A lock older than 3 hours is ignored,
// so a crashed run cannot block sending for good.
const s = $('Read Settings').first().json || {};
const lock = DateTime.fromISO(String(s['WF3 Lock'] || '').trim());
if (lock.isValid && lock > $now.minus({ hours: 3 })) {
  return [{ json: { locked: true, since: lock.toISO(), waiting: $input.all().length } }];
}
return $input.all();

// The row changed after this run started (already sent, un-approved, or stage changed): do not send it.
const was = $('Loop Over Drafts').item.json;
return { json: { 'Lead ID': was['Lead ID'], Company: was.Company, skip_reason: 'changed', stage_now: $json.Stage || '(row not found)', approved_now: $json.Approved || '', sent_at_now: $json['Sent At'] || '' } };

// The fresh row again (the sheet update before this replaced the item), plus who approved it.
// The dashboard writes a Log row for each approval: Workflow 'Dashboard', Step 'approve_first', Reason 'by <email>'.
const lead = $('Re-read lead').item.json;
// Safety: the row handed on must be the one that was just marked 'Sending'. If not, stop before anything is sent.
if (!lead || !lead['Lead ID'] || String(lead['Lead ID']) !== String($json['Lead ID'])) {
  throw new Error('WF3 stopped before sending: the row to send (' + (lead && lead['Lead ID']) + ') does not match the row marked Sending (' + $json['Lead ID'] + '). Set that row back to Drafted.');
}
let rows = [];
try { rows = $('Read Log').all(); } catch (e) {}
let approver = '';
for (let k = rows.length - 1; k >= 0; k--) {
  const j = rows[k].json || {};
  if (j.Workflow === 'Dashboard' && j['Lead ID'] === lead['Lead ID'] && j.Step === 'approve_first') { approver = String(j.Reason || '').replace(/^by\s+/, '').trim(); break; }
}
return { json: { ...lead, approved_by: approver || 'not recorded (Approved was set in the sheet)' } };
